import{z as A,x as d,o as l,c as p,q as r,j as E,D as t,d as s,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"以太网速率演进","description":"","frontmatter":{"title":"以太网速率演进","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ethernet-speeds.md","filePath":"cs/ethernet-speeds.md","lastUpdated":1791063341000}'),C={name:"cs/ethernet-speeds.md"};function B(h,a,P,c,D,m){const n=d("Mermaid");return l(),p("div",null,[a[2]||(a[2]=r('<h1 id="以太网速率演进" tabindex="-1">以太网速率演进 <a class="header-anchor" href="#以太网速率演进" aria-label="Permalink to &quot;以太网速率演进&quot;">​</a></h1><div class="epigraph"><p>从 10 Mb/s 共享到 800 Gb/s 串行，MAC 帧几乎不动，变的是 PCS、FEC 与并行通道数。</p><footer>—— 据 IEEE 802.3 各代标准；Metcalfe and Boggs, 1976 对照整理</footer></div><p><a href="/cs/optical-transceivers-wdm">上一课</a>给出模块与波长。缺口是<strong>速率档如何叠上去</strong>：10/100/1000/10G/25G/40G/100G/400G……同一<a href="/cs/frame-mac">帧与 MAC</a> 格式，PHY 换调制、块码、FEC 与 lane。本课不把自协商状态机写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若每升一档就改帧格式，交换芯片与抓包工具全断代。802.3 的策略：MAC 服务不变，介质相关子层升级。百兆 4B/5B，千兆 8B/10B，10G 64B/66B，25G+ 常配 RS-FEC。40G/100G 用多 lane 绑定（如 4×25G）。标称速率是 MAC 侧净荷量级，毛速率含编码——接住前几课的开销账。</p><p>共享同轴的 10BASE5 已退出；当代默认全双工点到点。CSMA/CD 留在主干课对照，不在本档复活。</p><p><span class="marginnote">802.3 用「BASE」命名介质与编码。多 lane 对齐是 PCS 的 deskew，不是 LACP。LACP 是后课把多条已成立链路绑成一条逻辑链路。</span></p><h3 id="升速改-phy-不改帧" tabindex="-1">升速改 PHY 不改帧 <a class="header-anchor" href="#升速改-phy-不改帧" aria-label="Permalink to &quot;升速改 PHY 不改帧&quot;">​</a></h3><p>MAC 服务稳定，变的是 PCS、FEC 与 lane。多 lane deskew 不是 LACP。标称速率对照毛符号率时必须先扣块码。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列演进轴：符号率、每符号比特、lane 数、FEC。画：MAC → Reconciliation → PCS/PMA → PMD。强调 25G 单 lane 成为数据中心积木，100G 常 4×25 或 2×50。不要背年份表当课。</p>',11)),(l(),E(i,null,{default:t(()=>[o(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAC%5B%22%E4%B8%8D%E5%8F%98%E7%9A%84%20MAC%20%E5%B8%A7%22%5D%20--%3E%20PCS%5B%22%E6%8D%A2%E4%BB%A3%E7%9A%84%20PCS%2FFEC%22%5D%0A%20%20PCS%20--%3E%20LANE%5B%221%20%E6%88%96%20N%20%E6%9D%A1%20SerDes%22%5D%0A%20%20LANE%20--%3E%20PMD%5B%22%E9%93%9C%E6%88%96%E5%85%89%20PMD%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"数字实例：千兆口的 8B/10B 把 8 位数据编成 10 位符号，毛速率 1.25 Gb/s，扣掉两成编码开销才净得 1 Gb/s；10G 换成 64B/66B，开销只剩约 3%。同一张帧格式下换块码，本身就「省」回了一批带宽——这就是换代要动的层。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[s("容量课的 \\(C\\) 随工艺与调制上升；以太网把上升收成可互操作的档。交换机「40G 口」可能是 4 条 10G lane，对 IP 仍是一个接口。主干"),e("a",{href:"/cs/vlan"},"VLAN"),s(" 标签加在 MAC 上，与速率档正交。")],-1)),(l(),E(i,null,{default:t(()=>[o(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E4%B8%80%E5%B8%A7%20MAC%20%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20E%5B%2264B%2F66B%20%E5%9D%97%E7%A0%81%E7%BC%96%E7%A0%81%22%5D%0A%20%20E%20--%3E%20FEC%5B%22RS-FEC%20%E9%99%84%E5%8A%A0%E6%A0%A1%E9%AA%8C%E4%BD%8D%22%5D%0A%20%20FEC%20--%3E%20S%5B%22%E5%AD%97%E8%8A%82%E8%BD%AE%E6%B5%81%E5%88%86%E5%8F%91%E5%88%B0%204%20%E6%9D%A1%20lane%22%5D%0A%20%20S%20--%3E%20DW%5B%22%E5%90%84%20lane%20deskew%20%E6%A0%A1%E6%AD%A3%E6%97%B6%E5%B7%AE%22%5D%0A%20%20DW%20--%3E%20O%5B%22PMD%20%E7%94%B5%E5%85%89%E8%BD%AC%E6%8D%A2%E4%B8%8A%E7%BA%BF%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">术语翻译：lane 就是芯片里一条独立的串行「车道」——与其把一条车道修到 100 Gb/s，不如并排开 4 条 25 Gb/s 的。PCS 负责把一帧的字节轮流分上车、到对面再按序拼回来；deskew 就是校正四条车道到达时间的先后差，谁慢了就等谁。</span></p><p>FEC 使净荷时延增加几十到几百纳秒，对存储 RoCE 后课敏感，本课只点名。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 802.3cg 单对以太网的全部工业剖面。自协商与双工是下一课。后课默认：升速改 PHY，不改以太网帧语义。</p><p>营销「无损以太网」是 PFC 后课，不是速率档的性质。</p><p><span class="marginnote">常见误区：初学者以为标称 100G 就能发满 100G 的应用数据——实际要扣块码、FEC、帧头与帧间隔等毛开销；另一个误区是把「40G 口」当成一整条通道，它内部常是 4 条 10G lane，用一根一分四线缆就能当 4 个 10G 口使，这是 PHY 结构，不是配置出来的功能。</span></p><p>下一课<a href="/cs/autonegotiation">自协商与双工</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>帧格式稳定；PCS、FEC、lane 承载升速。</li><li>标称速率含编码约定，对照毛符号率。</li><li>多 lane 是 PHY 绑定，不是 LACP。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：IEEE 802.3；Metcalfe–Boggs, 1976。</li></ul>',9))])}const u=A(C,[["render",B]]);export{S as __pageData,u as default};
